def palindrome_cube_finder(n: int) -> str:
    x = 1
    ans = ""

    while x**3 <= n:
        s = str(x**3)
        l = len(s)
        kai = True
        for i in range(l//2):
            if s[i] != s[l-i-1]:
                kai = False
                break
        if kai:
            ans = s
        x += 1
    return ans
